// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    address owner;

    function setUp() public {
        c = new RoundFactory();
        owner = address(0xBEEF);
        vm.prank(owner);
        c.initialize();
    }

    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        vm.assume(newOwner != address(c));

        vm.prank(owner);
        c.transferOwnership(newOwner);

        assertTrue(c.owner() == newOwner, "owner must become newOwner after transferOwnership");
    }
}
